/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);
    logic state_r;

    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state_r <= 1'b1;
        else if ("'!in)
            state_r <= ~state_r;
    end

    assign out = state_r;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic areset = 0;
    logic in = 0;
    wire out;
    logic expected;
    integer sequence_id;
    integer bit_id;
    TopModule dut (.clk(clk), .areset(areset), .in(in), .out(out));
    always #5 clk = ~clk;

    task automatic check_output;
        if (out !== expected)
            $fatal(1, "FAIL expected=%b actual=%b", expected, out);
    endtask

    initial begin
        #2;
        areset = 1;
        expected = 1;
        #1;
        check_output();
        #3;
        check_output();
        @(negedge clk);
        areset = 0;
        for (sequence_id = 0; sequence_id < 256; sequence_id = sequence_id + 1) begin
            // Reset between sequences, away from a rising clock edge.
            #1;
            areset = 1;
            expected = 1;
            #1;
            check_output();
            areset = 0;
            for (bit_id = 0; bit_id < 8; bit_id = bit_id + 1) begin
                in = (sequence_id >> bit_id) & 1;
                #1;
                check_output(); // Moore output must not react to input alone.
                @(posedge clk);
                if (!in) expected = ~expected;
                #1;
                check_output();
                @(negedge clk);
            end
        end
        // Keep reset asserted across several clock edges.
        areset = 1;
        expected = 1;
        repeat (3) begin
            @(posedge clk);
            #1;
            check_output();
        end
        $display("PASS: exhaustive 8-input sequences, asynchronous reset, hold and toggle transitions");
        $finish;
    end
    initial begin
        #30000;
        $fatal(1, "FAIL: timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
else
    simulation_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > development_status.log
cat development_status.log compile.log simulation.log'

